class Product { final String id,name,categoryId,brand,description,unit; final List<String> images; final double price,discountPrice,avgRating; final int stockQuantity; final bool isAvailable; const Product({required this.id,required this.name,required this.categoryId,this.brand='',this.description='',this.unit='',this.images=const [],required this.price,this.discountPrice=0,this.avgRating=0,this.stockQuantity=0,this.isAvailable=true}); double get salePrice => discountPrice > 0 && discountPrice < price ? discountPrice : price; factory Product.fromMap(String id, Map<String,dynamic> m) => Product(id:id,name:m['name'] ?? '',categoryId:m['categoryId'] ?? '',brand:m['brand'] ?? '',description:m['description'] ?? '',unit:m['unit'] ?? '',images:List<String>.from(m['images'] ?? const []),price:(m['price'] ?? 0).toDouble(),discountPrice:(m['discountPrice'] ?? 0).toDouble(),avgRating:(m['avgRating'] ?? 0).toDouble(),stockQuantity:m['stockQuantity'] ?? 0,isAvailable:m['isAvailable'] ?? true); }
